use crate::i18n::Language;

pub(crate) fn sections(language: Language) -> &'static [(&'static str, &'static str)] {
    match language {
        Language::English => EN,
        Language::Russian => RU,
    }
}

const EN: &[(&str, &str)] = &[
    ("Supported keyboard and firmware", "This desktop candidate targets the wired AK820 and the ten exact v0.6.0-beta.2 profile images. The earlier full permanent alpha.3 image remains a separate compatibility path. Connection verifies installed CODE, manifest, layout and required settings before editing. Unknown, custom, trial and mismatched images are rejected. Source and offline tests do not establish physical qualification."),
    ("Read and write settings", "Read the keyboard settings before editing. Available keys and module settings follow the verified profile. Each persistent edit checks its acknowledgement and readback; typed module edits also compare complete NVM. If any operation fails, choose Read settings again before continuing. The application never retries a failed write automatically."),
    ("Layers and modules", "The editor supports 6 layers, 83 keys and one encoder with two rotation directions. Tap Dance and Key Overrides have eight entries where the profile includes them. QMK Settings exposes only advertised IDs; Auto Shift timeout is editable only in Typing. Matrix, encoder and macro actions have distinct limits. Inactive saved module fields are preserved. Runtime Dynamic Macros and temporary firmware modes are not device backups."),
    ("Macros and Combo", "There are 16 macros with a total capacity of 8192 bytes. Text is ASCII; Vial macro codes 1–7 are supported. To unlock macro editing, choose Unlock, then hold Esc and Left Ctrl for 3 seconds. Unlock starts only after an explicit action. Up to eight two-key Combos are supported. Beta.2 Combo timing comes from its active setting; alpha.3 uses 40 ms."),
    ("Lighting and local palettes", "Built-in effects are Off, Solid, Breathing, Cycle all, Cycle left/right and Reactive. Direct is available in Main, Game, Mmo and Creative. The static palette remains format v1; the additional scene editor uses format v2 with up to 16 ordered/enabled layers, 82-LED masks, Solid/Gradient/Wave/Breathing/Rain, horizontal/vertical axes, opacity and 250–60000 ms periods. Quiet-hours brightness uses local wall-clock time, includes its start and excludes its end, and supports overnight intervals. A local preview and 32-state undo/redo are provided. Select by click, Ctrl/Cmd-click or Shift-click; drag selection is not supported. Live playback has a queue of one and a conservative application cap of 10 frames/s, not a hardware-qualified rate. Priority operations pause and drop pending frames; playback resumes only in the same intact session. A UI suspension over two seconds, disconnect, generation/profile change, error or physical mode/speed/HSV change stops playback without retry or restore. Stop leaves sent RAM colors. Explicit Off sends one black frame only in a safe intact session. No built-in mode is automatically restored; select it explicitly. There is no persistent scheduler daemon, automatic playback start, per-frame NVM save, palette getter or atomic frame commit. Direct colors remain volatile. Music, screen, game integrations and OpenRGB SDK compatibility remain planned."),
    ("Offline projects", "Start with --demo-ak820 to edit independent examples for Main, Game, Mmo, Typing, Code, Pointer, Onehand, Creative, Shortcuts and Multios without discovering a device. Switching retains changes in memory. Save/Open project uses .ak820project.json version 2 with exact release, catalog and image identity. It is an example project, not a device backup. Version 1 beta.1 projects require manual migration. RGB palette presets are separate files. Outside demo mode, catalog selection previews a profile and never changes installed firmware."),
    ("Firmware files", "Open Firmware files, choose the target profile, and select three local files: prepared firmware of exactly 51,136 bytes, a complete current snapshot of 65,536 bytes, and your personal OEM recovery copy of 65,536 bytes. Choose Check files to verify that the firmware matches the profile and the snapshot is compatible with the recovery copy. Hashes and file details are available in the result. A successful check confirms the selected file contents only; it cannot confirm that the snapshot is current or came from the connected keyboard. Use Install firmware for a separate device-bound preview and explicit flash confirmation. Keep your OEM recovery copy private."),
    ("Backups and restore preview", "Open Backups, choose a folder, then choose Read complete snapshot for a verified beta.2 keyboard with no pending edits. The application checks replies against saved settings. If a check fails or reading is cancelled, it stops without retry. The complete snapshot stays in memory until you choose Save new backup; saving creates and rechecks a separate backup folder. Backup file operations support Linux, macOS and Windows with platform-specific filesystem guarantees. Restore starts from the immutable preview and requires a matching fresh complete capture, a verified safety backup and a fresh Esc + Left Ctrl three-second hold. Each whitelisted setter runs once and is checked; final full ROM and settings are verified. Errors stop without retry or automatic rollback. Read-only sessions refuse restore; stopped RGB is not resumed automatically. Reset to release defaults uses the same protected restore process and keeps inactive or reserved data. Deleting an inspected backup requires a separate permanent-deletion confirmation. .entlayout is a partial editor snapshot, not a complete backup. .ak820project.json stores offline examples. RGB palettes and scenes are separate local files; volatile RGB colors are not included in the device backup."),
    ("Install firmware and OEM recovery", "Open Install firmware, explicitly select the installation device and a backup folder, and choose a bundled profile or exact supported prepared file. The bundled beta2 firmware requires prerelease opt-in. Check release status when online; cached metadata can miss a later withdrawal while offline. Preparation reads the current complete image. Preserving settings requires a verified capture and compatible transition; defaults require explicit selection. Review the hashes and settings effect, then choose Start flashing. Project images request a fresh Esc + Left Ctrl hold. A durable safety copy is saved before erase. The single attempt verifies the complete ROM; failure stops without retry or automatic recovery. Saved safety paths remain visible after failure. OEM rollback requires the original private first-capture snapshot, this application's local receipt, the same USB port and a nonempty device serial; unsupported ownership blocks rollback. Do not share OEM data. Physical flash and recovery remain unqualified."),
    ("OS layout helper", "Enable the OS helper and map EN/RU to normal, off, on or slow breathing. Unknown layouts release the override; unsupported Wayland compositors cannot report a layout. These preferences stay on the computer. The helper pauses while another operation owns the device and stops refreshing after an error. Closing the interface releases the editor and keeps the enabled helper; reopen AK Configurator to return. Explicit Quit exits. --ak820-helper starts without a GUI; minimized autostart also uses the helper when enabled. The temporary firmware indication expires within three seconds without refresh."),
];

const RU: &[(&str, &str)] = &[
    ("Поддерживаемая клавиатура и прошивка", "Эта пробная версия компаньона рассчитана на проводную AK820 и десять точных образов профилей v0.6.0-beta.2. Полная постоянная alpha.3 сохранена как отдельный путь совместимости. Перед редактированием проверяются установленный CODE, манифест, раскладка и обязательные настройки. Неизвестные, пользовательские, пробные и несовпадающие образы отклоняются. Исходники и офлайн-тесты не заменяют проверку на устройстве."),
    ("Чтение и запись настроек", "Перед редактированием прочитайте настройки клавиатуры. Доступные действия и настройки модулей определяются проверенным профилем. Сохраняемое изменение проверяет подтверждение и чтение результата; типизированные настройки дополнительно сравнивают всё NVM. При ошибке выберите «Прочитать настройки снова». Автоматического повторения неудачной записи нет."),
    ("Слои и модули", "Редактор поддерживает 6 слоёв, 83 клавиши и один энкодер с двумя направлениями вращения. Tap Dance и Key Overrides содержат по восемь записей в профилях, где эти функции включены. QMK Settings показывает только объявленные ID; интервал Auto Shift доступен лишь в Typing. Матрица, энкодер и действия макросов имеют разные ограничения. Неактивные сохранённые поля модулей сохраняются. Временные Dynamic Macros и режимы прошивки не входят в резервную копию."),
    ("Макросы и Combo", "Доступно 16 макросов общим объёмом до 8192 байт. Текст — ASCII; поддерживаются коды макросов Vial 1–7. Для разблокировки редактирования выберите Unlock, затем удерживайте Esc и левый Ctrl 3 секунды. Разблокировка начинается только после явного действия. Поддерживается до восьми двухклавишных Combo. В beta.2 их интервал задаётся активной настройкой; в alpha.3 он равен 40 мс."),
    ("Подсветка и локальные палитры", "Встроенные эффекты: выключено, постоянный цвет, дыхание, смена цветов, волна и реакция на нажатия. Direct доступен в Main, Game, Mmo и Creative. Формат статической палитры v1 сохранён; дополнительный редактор сцен использует формат v2: до 16 упорядоченных/включаемых слоёв, маски на 82 LED, Solid/Gradient/Wave/Breathing/Rain, горизонтальная/вертикальная ось, непрозрачность и периоды 250–60000 мс. Яркость в тихие часы ограничивается по местному времени: начало включено, конец исключён, поддерживаются интервалы через полночь. Есть локальный предпросмотр и отмена/повтор на 32 состояния. Выбор — щелчком, Ctrl/Cmd или Shift; перетаскивание не поддерживается. Живое воспроизведение использует очередь ёмкостью один и консервативный предел приложения 10 кадров/с, не квалифицированный на оборудовании. Приоритетные операции приостанавливают поток и удаляют ожидающие кадры; он возобновляется только в том же целостном сеансе. Приостановка интерфейса дольше двух секунд, отключение, смена поколения/профиля, ошибка или физическая смена режима/скорости/HSV останавливают поток без повторов и восстановления. Остановка оставляет отправленные цвета в RAM. Явный Off отправляет один чёрный кадр только в безопасном целостном сеансе. Встроенный режим автоматически не восстанавливается — выберите его явно. Нет постоянного фонового планировщика, автоматического старта, записи NVM на каждый кадр, чтения палитры или атомарной фиксации кадра. Цвета Direct временные. Музыка, экран, игровые интеграции и совместимость с OpenRGB SDK остаются в плане."),
    ("Офлайн-проекты", "Режим --demo-ak820 открывает независимые примеры Main, Game, Mmo, Typing, Code, Pointer, Onehand, Creative, Shortcuts и Multios без поиска устройств. При переключении изменения остаются в памяти. Сохранение и открытие проекта используют .ak820project.json версии 2 с точной идентичностью релиза, каталога и образа. Это проект примера, а не копия устройства. Для файлов beta.1 версии 1 нужна ручная миграция. Пресеты палитры RGB сохраняются отдельно. Вне деморежима выбор в каталоге показывает возможности профиля и не меняет установленную прошивку."),
    ("Файлы прошивки", "Откройте «Файлы прошивки», выберите целевой профиль и укажите три локальных файла: подготовленную прошивку ровно 51 136 байт, текущий полный снимок 65 536 байт и личную OEM-копию восстановления 65 536 байт. Нажмите «Проверить файлы», чтобы проверить соответствие прошивки профилю и совместимость снимка с копией восстановления. В результате доступны хеши и сведения о файлах. Успешная проверка подтверждает только содержимое выбранных файлов: она не подтверждает, что снимок актуален или получен с подключённой клавиатуры. Для установки откройте «Установить прошивку»: это отдельный план с проверкой подключённого устройства и явным подтверждением. Не публикуйте личную OEM-копию восстановления."),
    ("Резервные копии и предпросмотр восстановления", "Откройте «Резервные копии», выберите папку, затем нажмите «Прочитать полный снимок» для проверенной клавиатуры beta.2 без ожидающих изменений. Приложение сверяет ответы с сохранёнными настройками. Если проверка не проходит или чтение отменено, оно останавливается без повтора. Полный снимок остаётся в памяти до нажатия «Сохранить новую копию»; сохранение создаёт отдельную папку и повторно проверяет копию. Файловые операции поддерживают Linux, macOS и Windows с гарантиями конкретной платформы. Восстановление запускается из неизменяемого предпросмотра и требует совпадающего свежего полного снимка, проверенной защитной копии и нового удержания Esc + левого Ctrl три секунды. Каждая разрешённая запись выполняется один раз и проверяется; затем проверяются полный ROM и настройки. При ошибке операция останавливается без повтора и автоматического отката. Сеанс только для чтения запрещает восстановление; остановленный RGB автоматически не возобновляется. Сброс к настройкам выпуска проходит через тот же защищённый процесс и сохраняет неактивные и резервные данные. Удаление просмотренной копии требует отдельного подтверждения безвозвратного удаления. .entlayout — частичный снимок редактора, а не полная копия. .ak820project.json хранит офлайн-примеры. RGB-палитры и сцены — отдельные локальные файлы; временные RGB-цвета не входят в копию устройства."),
    ("Установка прошивки и возврат OEM", "Откройте «Установить прошивку», явно выберите устройство и папку защитных копий, затем встроенный профиль или точный поддерживаемый подготовленный файл. Для встроенной beta2 нужно разрешить предварительную версию. При наличии сети проверьте статус выпуска; без сети более поздний отзыв может быть неизвестен. Подготовка читает текущий полный образ. Сохранение настроек требует проверенного снимка и совместимого перехода; настройки по умолчанию выбираются явно. Проверьте суммы и влияние на настройки, затем нажмите «Начать прошивку». Для образов проекта потребуется новое удержание Esc + левого Ctrl. До стирания сохраняется проверенная защитная копия. Единственная попытка завершается проверкой полного ROM; при ошибке нет автоматического повтора или восстановления. Пути сохранённых копий остаются видимыми и при ошибке. Откат OEM требует исходного закрытого снимка первого чтения, локальной записи этого приложения, того же USB-порта и непустого серийного номера; без доказанной принадлежности откат блокируется. Не публикуйте OEM-данные. Физическая установка и восстановление ещё не квалифицированы."),
    ("Помощник раскладки OS", "Включите помощник OS и сопоставьте EN/RU обычную индикацию, выключение, включение или медленное дыхание. Неизвестная раскладка возвращает обычную индикацию; неподдерживаемый композитор Wayland не сообщает раскладку. Настройки хранятся на компьютере. Помощник уступает устройство другим операциям и прекращает обновление после ошибки. При закрытии интерфейса редактор освобождается, а включённый помощник остаётся; для возврата откройте AK Configurator снова. Явный выход завершает приложение. --ak820-helper запускает помощник без GUI; свёрнутый автозапуск тоже использует включённый помощник. Без обновления временная индикация прошивки истекает за три секунды."),
];
